// Package commitmsg verifies the SeedGrid commit message policy.
//
// Rules:
//   - Subject in Conventional Commits format: type[(scope)][!]: description
//   - Exempt: Merge and Revert generated by git
//   - No Co-Authored-By trailer
//   - Non-empty message
package commitmsg

import (
	"regexp"
	"strings"
)

// subjectPattern covers Conventional Commits: type[(scope)][!]: description.
// scope accepts [A-Za-z0-9._/#-]; description starts with a non-space character.
var subjectPattern = regexp.MustCompile(`^(feat|fix|chore|docs|refactor|test|perf|ci|build|style|revert)(\([A-Za-z0-9._/#-]+\))?!?: \S`)

// exemptPrefixes are messages generated by git itself; they are not checked.
var exemptPrefixes = []string{"Merge ", `Revert "`}

// coauthorPattern matches any Co-Authored-By line, in any case,
// with optional spaces before and after the colon.
var coauthorPattern = regexp.MustCompile(`(?im)^\s*co-authored-by\s*:`)

// Check returns the message violations. Empty = ok.
// It does not discard comments — that is the responsibility of the -file mode (see StripComments).
func Check(msg string) []string {
	var violations []string
	if strings.TrimSpace(msg) == "" {
		return append(violations, "empty commit message")
	}

	// Subject: first line without trailing spaces.
	subject := ""
	if idx := strings.Index(msg, "\n"); idx >= 0 {
		subject = msg[:idx]
	} else {
		subject = msg
	}
	subject = strings.TrimRight(subject, " \t")

	// Exempt: Merge/Revert generated by git are not checked.
	exempt := false
	for _, p := range exemptPrefixes {
		if strings.HasPrefix(subject, p) {
			exempt = true
			break
		}
	}

	if !exempt {
		if !subjectPattern.MatchString(subject) {
			violations = append(violations,
				"subject not in the format <type>[(<scope>)][!]: <description> "+
					"(types: feat, fix, chore, docs, refactor, test, perf, ci, build, style, revert)")
		}
	}

	// Co-authorship trailer prohibited anywhere in the message.
	if coauthorPattern.MatchString(msg) {
		violations = append(violations, "Co-Authored-By trailer is not allowed")
	}

	return violations
}

// StripComments removes lines starting with "#" (git comments
// in the commit-msg hook message file).
func StripComments(msg string) string {
	lines := strings.Split(msg, "\n")
	kept := make([]string, 0, len(lines))
	for _, line := range lines {
		if strings.HasPrefix(line, "#") {
			continue
		}
		kept = append(kept, line)
	}
	return strings.Join(kept, "\n")
}
